import subprocess

# Get all symbols sorted by address
result = subprocess.run(['aarch64-linux-gnu-nm', '-n', '-C', 'libmonosgen-2.0.so.dbg'], capture_output=True, text=True)
symbols = []
for line in result.stdout.splitlines():
