    if len(parts) == 3 and parts[0].strip():
        try:
            addr = int(parts[0], 16)
            symbols.append((addr, parts[2]))
        except ValueError:
            pass

# Look up addresses
targets = [0x2f4b20, 0x2f4c84]
for t in targets:
    found = None
    for i, (addr, name) in enumerate(symbols):
        if addr > t:
            break
        found = (addr, name)
    if found:
        print(f'0x{t:x} -> {found[1]} (+0x{t - found[0]:x})')
    else:
        print(f'0x{t:x} -> ??')
"

