import subprocess

# The addresses 0x2f4b20 and 0x2f4c84 fall in the .in_labels data which is the computed goto jump table
# for mono_interp_exec_method. These PCs in the backtrace are likely code addresses that were stored
# in the jump table. Let's check if the SGen worker thread is actually executing code in a different function.
# Let's look for function symbols (type t/T) around these addresses
result = subprocess.run(['aarch64-linux-gnu-nm', '-n', '-C', 'libmonosgen-2.0.so.dbg'], capture_output=True, text=True)
symbols = []
for line in result.stdout.splitlines():
    parts = line.split(' ', 2)
    if len(parts) == 3 and parts[0].strip():
        try:
            addr = int(parts[0], 16)
            symbols.append((addr, parts[1], parts[2]))
        except ValueError:
            pass

# Find nearest code (t/T) symbol before these addresses  
targets = [0x2f4b20, 0x2f4c84]
for t in targets:
    found = None
    for addr, typ, name in symbols:
        if addr > t:
            break
        if typ in ('t', 'T', 'W'):
            found = (addr, name)
    if found:
        print(f'0x{t:x} -> {found[1]} (at 0x{found[0]:x}, +0x{t - found[0]:x})')
"

