import subprocess

# Let's try using the .symtab from the debug file to find what functions
# actually contain these addresses. Maybe these are in thunks/veneers.
# Try readelf --dyn-syms on the main binary for FUNC symbols
result = subprocess.run(['aarch64-linux-gnu-readelf', '-s', 'libmonosgen-2.0.so.dbg'], capture_output=True, text=True)
# Parse symbols, find functions that span these addresses
funcs = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 8 and parts[3] == 'FUNC' and parts[1] != '0000000000000000':
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            name = parts[7]
            if size > 0:
                funcs.append((addr, size, name))
        except (ValueError, IndexError):
            pass

targets = [0x2f4b20, 0x2f4c84]
for t in targets:
    found = None
    for addr, size, name in funcs:
        if addr <= t < addr + size:
            found = (addr, size, name)
            break
    if found:
        print(f'0x{t:x} -> {found[2]} (0x{found[0]:x}, size={found[1]})')
    else:
        print(f'0x{t:x} -> not within any FUNC symbol')
"

